14	// timeFmt 是命令行展示时间的格式（JSON 文件内使用 RFC3339）。
15	const timeFmt = "2006-01-02 15:04:05 -0700"
16	
17	// newFlagSet 为子命令准备统一的解析器：错误不自动退出，也不自行打印，
18	// 全部交由 parseFlags 统一输出，避免重复提示。
19	func newFlagSet(name string, _ io.Writer) *flag.FlagSet {
20		fs := flag.NewFlagSet(name, flag.ContinueOnError)
21		fs.SetOutput(io.Discard)
22		fs.Usage = func() {}
23		return fs
24	}
25	
26	// parseFlags 解析子命令参数。第二个返回值是退出码；ok=false 时应直接退出。
27	func parseFlags(fs *flag.FlagSet, argv []string, stdout, stderr io.Writer, printCmdHelp func(io.Writer)) (ok bool, code int) {
28		if err := fs.Parse(argv); err != nil {
29			if errors.Is(err, flag.ErrHelp) {
30				printCmdHelp(stdout)
31				return false, exitOK
32			}
33			fmt.Fprintf(stderr, "%s %s: %v；运行 %s %s --help 查看用法\n", appName, fs.Name(), err, appName, fs.Name())
34			return false, exitUsage
35		}
36		if fs.NArg() > 0 {
37			fmt.Fprintf(stderr, "%s %s: 未知参数 %q；运行 %s %s --help 查看用法\n", appName, fs.Name(), fs.Arg(0), appName, fs.Name())
38			return false, exitUsage
39		}
40		return true, 0
41	}
