276	// cleanParcelList 清洗并校验可重复的 --parcel 参数：逐个去除两端空白、
277	// 不可为空、集合不可为空且编号不可重复。
278	func cleanParcelList(raw []string) ([]string, error) {
279		if len(raw) == 0 {
280			return nil, fmt.Errorf("包裹集合不可为空，至少需要一个 --parcel")
281		}
282		clean := make([]string, 0, len(raw))
283		seen := make(map[string]bool, len(raw))
284		for _, v := range raw {
285			id, err := cleanID("包裹编号", v)
286			if err != nil {
287				return nil, err
288			}
289			if seen[id] {
290				return nil, fmt.Errorf("包裹集合中编号 %q 重复", id)
291			}
292			seen[id] = true
293			clean = append(clean, id)
294		}
295		return clean, nil
296	}
