356		fs := newFlagSet("receipt", stderr)
357		fs.StringVar(&dataFile, "data", dataFile, "本地台账数据文件路径")
358		request := fs.String("request", "", "回执请求号（用于去重）")
359		batch := fs.String("batch", "", "配送批次号")
360		parcel := fs.String("parcel", "", "包裹编号")
361		result := fs.String("result", "", "回执结果：签收 或 失败")
362		reason := fs.String("reason", "", "失败原因（结果为失败时必填，签收时不可带）")
363		if ok, code := parseFlags(fs, argv, stdout, stderr, printReceiptHelp); !ok {
364			return code
365		}
366	
367		cleanReq, err := cleanID("回执请求号", *request)
368		if err != nil {
369			fmt.Fprintf(stderr, "%s receipt: %v\n", appName, err)
370			return exitBusiness
371		}
372		cleanBatch, err := cleanID("批次号", *batch)
373		if err != nil {
374			fmt.Fprintf(stderr, "%s receipt: %v\n", appName, err)
375			return exitBusiness
376		}
377		cleanParcel, err := cleanID("包裹编号", *parcel)
378		if err != nil {
379			fmt.Fprintf(stderr, "%s receipt: %v\n", appName, err)
380			return exitBusiness
381		}
382		cleanResult, err := cleanID("回执结果", *result)
383		if err != nil {
384			fmt.Fprintf(stderr, "%s receipt: %v\n", appName, err)
385			return exitBusiness
386		}
387		if cleanResult != resultSigned && cleanResult != resultFailed {
388			fmt.Fprintf(stderr, "%s receipt: 回执结果只能是 %q 或 %q，得到 %q\n", appName, resultSigned, resultFailed, cleanResult)
389			return exitBusiness
390		}
391		cleanReason := strings.TrimSpace(*reason)
392		if cleanResult == resultFailed && cleanReason == "" {
393			fmt.Fprintf(stderr, "%s receipt: 结果为失败时原因不可为空或仅含空白\n", appName)
394			return exitBusiness
395		}
396		if cleanResult == resultSigned && cleanReason != "" {
397			fmt.Fprintf(stderr, "%s receipt: 结果为签收时不可带原因\n", appName)
398			return exitBusiness
399		}
400	
401		store, err := Open(dataFile)
402		if err != nil {
403			fmt.Fprintf(stderr, "%s receipt: %v\n", appName, err)
404			return exitBusiness
405		}
406		res, replayed, err := store.Receipt(cleanReq, cleanBatch, cleanParcel, cleanResult, cleanReason, now())
407		if err != nil {
408			fmt.Fprintf(stderr, "%s receipt: %v\n", appName, err)
409			return exitBusiness
410		}
411	
412		headline := "回执成功"
413		if replayed {
414			headline = "回执成功（请求号重复提交，返回首次保存的结果，未再追加轨迹）"
415		}
416		fmt.Fprintf(stdout, "%s\n请求号: %s\n批次号: %s\n包裹编号: %s\n结果: %s\n",
417			headline, res.Request, res.Batch, res.Parcel, res.Result)
418		if res.Result == resultFailed {
419			fmt.Fprintf(stdout, "原因: %s\n", res.Reason)
420		}
421		fmt.Fprintf(stdout, "发生时间: %s\n", res.Time.Format(timeFmt))
422		return exitOK
423	}
