425	// receiptFileRecord 是回执整批导入文件中的单条记录（JSON）。
426	type receiptFileRecord struct {
427		Request string `json:"request"`
428		Batch   string `json:"batch"`
429		Parcel  string `json:"parcel"`
430		Result  string `json:"result"`
431		Reason  string `json:"reason"`
432	}
433	
434	// loadReceiptImportFile 读取并解析回执整批导入文件。文件为有序且非空的
435	// JSON 数组，元素为 request/batch/parcel/result/reason 字段的对象；
436	// 文件只读，绝不改写。任一记录清洗后不合法或请求号在文件内重复，
437	// 都返回带记录位置的错误，整份不予导入。
438	func loadReceiptImportFile(path string) ([]ReceiptImportRecord, error) {
439		raw, err := os.ReadFile(path)
440		if err != nil {
441			return nil, fmt.Errorf("读取回执导入文件失败: %w", err)
442		}
443		dec := json.NewDecoder(bytes.NewReader(raw))
444		dec.DisallowUnknownFields()
445		var records []receiptFileRecord
446		if err := dec.Decode(&records); err != nil {
447			return nil, fmt.Errorf("解析回执导入文件失败: %w", err)
448		}
449		var extra any
450		if err := dec.Decode(&extra); err != io.EOF {
451			return nil, fmt.Errorf("解析回执导入文件失败: 回执列表之后存在多余内容")
452		}
453		if len(records) == 0 {
454			return nil, fmt.Errorf("回执导入文件必须是有序且非空的回执列表")
455		}
456	
457		clean := make([]ReceiptImportRecord, 0, len(records))
458		seen := make(map[string]bool, len(records))
459		for i, rawRec := range records {
460			rec, err := cleanReceiptImportRecord(rawRec)
461			if err != nil {
462				return nil, fmt.Errorf("第 %d 条记录: %w", i+1, err)
463			}
464			if seen[rec.Request] {
465				return nil, fmt.Errorf("第 %d 条记录: 回执请求号 %q 在文件内重复", i+1, rec.Request)
466			}
467			seen[rec.Request] = true
468			clean = append(clean, rec)
469		}
470		return clean, nil
471	}
472	
473	// cleanReceiptImportRecord 清洗并校验一条导入记录：各标识去除两端空白后不可为空；
474	// 结果为失败时必须给出清理后非空的原因，签收时不可带原因。
475	func cleanReceiptImportRecord(raw receiptFileRecord) (ReceiptImportRecord, error) {
476		var rec ReceiptImportRecord
477		var err error
478		if rec.Request, err = cleanID("回执请求号", raw.Request); err != nil {
479			return rec, err
480		}
481		if rec.Batch, err = cleanID("批次号", raw.Batch); err != nil {
482			return rec, err
483		}
484		if rec.Parcel, err = cleanID("包裹编号", raw.Parcel); err != nil {
485			return rec, err
486		}
487		if rec.Result, err = cleanID("回执结果", raw.Result); err != nil {
488			return rec, err
489		}
490		if rec.Result != resultSigned && rec.Result != resultFailed {
491			return rec, fmt.Errorf("回执结果只能是 %q 或 %q，得到 %q", resultSigned, resultFailed, rec.Result)
492		}
493		rec.Reason = strings.TrimSpace(raw.Reason)
494		if rec.Result == resultFailed && rec.Reason == "" {
495			return rec, fmt.Errorf("结果为失败时原因不可为空或仅含空白")
496		}
497		if rec.Result == resultSigned && rec.Reason != "" {
498			return rec, fmt.Errorf("结果为签收时不可带原因")
499		}
500		return rec, nil
501	}
