535	// Register 执行单件收件登记并将结果整体落盘。
536	func (s *Store) Register(id, station string, now time.Time) (*Parcel, error) {
537		if _, ok := s.data.Parcels[id]; ok {
538			return nil, fmt.Errorf("包裹编号 %q 已登记，不能重复登记", id)
539		}
540		p := &Parcel{
541			ID:         id,
542			Station:    station,
543			Status:     statusInStation,
544			Registered: now,
545			Trail: []Event{{
546				Op:      "收件",
547				Station: station,
548				Time:    now,
549			}},
550		}
551		s.data.Parcels[id] = p
552		if err := s.save(); err != nil {
553			delete(s.data.Parcels, id) // 落盘失败：回滚内存变更，保留原有有效数据
554			return nil, err
555		}
556		return p, nil
557	}
