568	// ActiveFreeze 返回一件包裹当前未解除异常单的冻结结果；包裹不存在或当前未冻结时返回 nil。
569	func (s *Store) ActiveFreeze(id string) *FreezeResult {
570		p, ok := s.data.Parcels[id]
571		if !ok {
572			return nil
573		}
574		if no := activeFreeze(p); no != "" {
575			return s.data.Freezes[no]
576		}
577		return nil
578	}
