384				`"batches":{"B1":{"batch":"B1","station":"A","courier":"张三","parcels":["P1"],"time":"2026-10-05T09:30:00Z","receipts":{}}},"aborts":{"A1":{` + abort + `}}}`,
385			"批次标记了不存在的中止": `{"version":1,"parcels":{"P1":{` + parcel + `,"trail":` + trail + `}},"handoffs":{},` +
386				`"batches":{"B1":{"batch":"B1","station":"A","courier":"张三","parcels":["P1"],"time":"2026-10-05T09:30:00Z","receipts":{},"abortedBy":"NOPE"}},"aborts":{"A1":{` + abort + `}}}`,
387			"收回集合与未回执成员不符": `{"version":1,"parcels":{"P1":{` + parcel + `,"trail":` + trail + `}},"handoffs":{},` +
388				`"batches":{"B1":{` + batch + `}},"aborts":{"A1":{"request":"A1","batch":"B1","station":"A","reason":"车辆故障","parcels":["P1","P2"],"time":"2026-10-05T10:00:00Z"}}}`,
389			"中止结果字段不完整": `{"version":1,"parcels":{"P1":{` + parcel + `,"trail":` + trail + `}},"handoffs":{},` +
390				`"batches":{"B1":{` + batch + `}},"aborts":{"A1":{"request":"A1","batch":"B1","station":"A","reason":"","parcels":["P1"],"time":"2026-10-05T10:00:00Z"}}}`,
391		}
392		for name, content := range cases {
