410	func TestCLIEndToEndAbort(t *testing.T) {
411		dbPath := t.TempDir() + "/ledger.json"
412		for _, id := range []string{"P001", "P002", "P003"} {
413			if _, _, code := runCLI(t, dbPath, "register", "--id", id, "--station", "站点A"); code != 0 {
414				t.Fatalf("登记失败: %d", code)
415			}
416		}
417		if _, _, code := runCLI(t, dbPath, "dispatch", "--batch", "B1", "--station", "站点A", "--courier", "张三",
418			"--parcel", "P001", "--parcel", "P002", "--parcel", "P003"); code != 0 {
419			t.Fatal("出站失败")
420		}
421		if _, _, code := runCLI(t, dbPath, "receipt", "--request", "RC1", "--batch", "B1", "--parcel", "P001", "--result", "签收"); code != 0 {
422			t.Fatal("回执失败")
423		}
424	
425		// 中止成功输出：首次收回集合与中止信息。
426		out, _, code := runCLI(t, dbPath, "abort", "--request", " A1 ", "--batch", "B1", "--reason", " 车辆故障全部收回 ")
427		if code != 0 || !strings.Contains(out, "中止成功") ||
428			!strings.Contains(out, "中止请求号: A1") || !strings.Contains(out, "批次号: B1") ||
429			!strings.Contains(out, "出发站: 站点A") || !strings.Contains(out, "中止原因: 车辆故障全部收回") ||
430			!strings.Contains(out, "收回包裹（2 件）") || !strings.Contains(out, "- P002") || !strings.Contains(out, "- P003") {
431			t.Fatalf("中止输出不符: code=%d out=%s", code, out)
432		}
433	
434		// batch：已中止，展示真实回执、收回成员与中止信息，收回件不列为未回执。
435		out, _, code = runCLI(t, dbPath, "batch", "--id", "B1")
436		if code != 0 || !strings.Contains(out, "批次状态: 已中止") ||
437			!strings.Contains(out, "中止请求号: A1") || !strings.Contains(out, "中止原因: 车辆故障全部收回") ||
438			!strings.Contains(out, "P001    已回执    结果: 签收") ||
439			!strings.Contains(out, "P002    已收回") || !strings.Contains(out, "P003    已收回") ||
440			strings.Contains(out, "未回执") {
441			t.Fatalf("中止后批次查询不符: code=%d out=%s", code, out)
442		}
443	
444		// query：收回轨迹完整可辨认。
445		out, _, code = runCLI(t, dbPath, "query", "--id", "P002")
446		if code != 0 || !strings.Contains(out, "当前状态: 在站") ||
447			!strings.Contains(out, "操作: 收回") || !strings.Contains(out, "批次号: B1") ||
448			!strings.Contains(out, "中止请求号: A1") || !strings.Contains(out, "原因: 车辆故障全部收回") {
449			t.Fatalf("收回后查询不符: code=%d out=%s", code, out)
450		}
451	
452		// 同号同内容重放：返回首次结果，不追加收回轨迹。
453		out, _, code = runCLI(t, dbPath, "abort", "--request", "A1", "--batch", "B1", "--reason", "车辆故障全部收回")
454		if code != 0 || !strings.Contains(out, "返回首次保存的结果") {
455			t.Fatalf("重复中止应重放: code=%d out=%s", code, out)
456		}
457		out, _, _ = runCLI(t, dbPath, "query", "--id", "P002")
458		if strings.Count(out, "操作: 收回") != 1 {
459			t.Fatalf("重放不得追加收回轨迹:\n%s", out)
460		}
461	
462		// 同号换内容：冲突。
463		_, errText, code := runCLI(t, dbPath, "abort", "--request", "A1", "--batch", "B1", "--reason", "别的原因")
464		if code != exitBusiness || !strings.Contains(errText, "冲突") {
465			t.Fatalf("中止请求号内容冲突应失败: code=%d err=%s", code, errText)
466		}
467	
468		// 换请求号再中止：拒绝。
469		_, errText, code = runCLI(t, dbPath, "abort", "--request", "A2", "--batch", "B1", "--reason", "再次中止")
470		if code != exitBusiness || !strings.Contains(errText, "已中止") {
471			t.Fatalf("重复中止批次应失败: code=%d err=%s", code, errText)
472		}
473	
474		// 收回件不能首次回执旧批次。
475		_, errText, code = runCLI(t, dbPath, "receipt", "--request", "RC2", "--batch", "B1", "--parcel", "P002", "--result", "签收")
476		if code != exitBusiness || !strings.Contains(errText, "不在批次") {
477			t.Fatalf("收回件回执旧批次应失败: code=%d err=%s", code, errText)
478		}
479	
480		// 收回件可再次出站并正常回执新批次。
481		if _, _, code := runCLI(t, dbPath, "dispatch", "--batch", "B2", "--station", "站点A", "--courier", "李四",
482			"--parcel", "P002", "--parcel", "P003"); code != 0 {
483			t.Fatal("收回件再次出站失败")
484		}
485		if _, _, code := runCLI(t, dbPath, "receipt", "--request", "RC3", "--batch", "B2", "--parcel", "P002", "--result", "签收"); code != 0 {
486			t.Fatal("新批次回执失败")
487		}
