		t.Fatal("整份拒绝时此次新增必须撤销，新号不得占用")
	}
	if _, ok := s.data.Receipts["RC3"]; ok {
		t.Fatal("迟到回执不得占用请求号")
	}
	p1, _ := s.Query("P001")
	if currentBatch(p1) != "B2" || len(p1.Trail) != 4 {
